<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,errorMessage,type Page} from '../../api/http'
import {useAuthStore} from '../../stores/auth'
import {selectAccessibility as vSelectAccessibility} from '../ebr/selectAccessibility'
import {states,type Product,type Package} from './model'
const route=useRoute(),router=useRouter(),auth=useAuthStore(),isProduct=computed(()=>route.meta.resource==='products')
const title=computed(()=>isProduct.value?'产品管理':'生产工艺'),endpoint=computed(()=>isProduct.value?'products':'process-packages'),root=computed(()=>`/process/${isProduct.value?'products':'packages'}`)
const keyword=ref(''),status=ref(''),productId=ref(''),error=ref(''),busy=ref(false),productOptions=ref<Product[]>([])
const data=ref<Page<Product|Package>>({items:[],total:0,page:0,size:20})
async function loadProductOptions(){if(isProduct.value||!auth.can('master:product:view'))return;try{const page=await api<Page<Product>>({url:'/products',params:{page:0,size:100,status:'ACTIVE'}});productOptions.value=page.items}catch{productOptions.value=[]}}
const columns=computed(()=>isProduct.value?[{title:'产品编码',dataIndex:'productCode'},{title:'产品名称',dataIndex:'productName'},{title:'剂型',dataIndex:'dosageForm'},{title:'规格',dataIndex:'specification'},{title:'状态',key:'status'},{title:'操作',key:'actions'}]:[{title:'生产工艺编码',dataIndex:'packageCode',width:170,className:'process-code-cell'},{title:'工艺名称',dataIndex:'packageName',key:'packageName',width:170,className:'process-name-cell'},{title:'版本',dataIndex:'processVersion',width:80},{title:'生效批准日期',dataIndex:'effectiveApprovedDate',width:120},{title:'工艺说明',dataIndex:'description',ellipsis:true,width:180},{title:'工序数',key:'operations',width:70},{title:'适用产品',key:'scope',width:170,className:'process-scope-cell'},{title:'状态',key:'status',width:80},{title:'配置状态',key:'definitionStatus',width:100},{title:'操作',key:'actions',width:130,fixed:'right' as const}])
async function load(page=0){busy.value=true;error.value='';try{const params={keyword:keyword.value,status:status.value,productId:productId.value,page,size:20};await router.replace({query:Object.fromEntries(Object.entries(params).filter(([,v])=>v!==''&&v!==undefined).map(([k,v])=>[k,String(v)]))});data.value=await api({url:`/${endpoint.value}`,params})}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function reset(){keyword.value='';status.value='';productId.value='';void load()}
function productScope(record:Product|Package){return 'applicableProducts' in record&&record.applicableProducts?.length?record.applicableProducts.map(p=>p.productName).join('、'):'通用工艺'}
function open(id?:string,edit=false){void router.push({path:`${root.value}/${id?`${id}${edit?'/edit':''}`:'create'}`,query:route.query})}
watch(()=>route.meta.resource,()=>{for(const [key,field] of Object.entries({keyword,status,productId}))field.value=String(route.query[key]??'');void load(Number(route.query.page??0));void loadProductOptions()},{immediate:true})
</script>
<template><main data-ui-template="T1" class="admin-page master-page t1-query-list" :class="{'process-package-list':!isProduct}" v-select-accessibility><header class="admin-page-header"><div><h1>{{title}}</h1></div><a-button v-if="auth.can(isProduct?'master:product:create':'process:package:create')" type="primary" @click="open()">＋ 新增</a-button></header>
<a-card title="查询条件" class="query-card"><form class="query-form" @submit.prevent="load()"><label><span class="form-field-label">编码 / 关键字</span><a-input v-model:value="keyword" allow-clear/></label><label><span class="form-field-label">状态</span><a-select show-search option-filter-prop="children" v-model:value="status" allow-clear style="min-width:140px"><a-select-option v-for="s in ['ACTIVE','INACTIVE']" :key="s" :value="s">{{states[s]}}</a-select-option></a-select></label><label v-if="!isProduct"><span class="form-field-label">适用产品</span><a-select v-model:value="productId" allow-clear show-search option-filter-prop="label" :options="productOptions.map(p=>({value:p.id,label:p.productName+'（'+p.productCode+'）'}))" placeholder="全部产品" style="min-width:220px"/></label><a-space><a-button type="primary" html-type="submit">查询</a-button><a-button @click="reset">重置</a-button></a-space></form></a-card>
<a-alert v-if="error" type="error" :message="error" show-icon/><a-card title="数据列表" class="result-card"><a-table :columns="columns" :data-source="data.items" :loading="busy" :pagination="false" row-key="id" :scroll="{x:isProduct?900:1250}"><template #bodyCell="{column,record}"><template v-if="column.key==='actions'"><a-button type="link" @click="open(record.id)">查看</a-button><a-button v-if="isProduct?auth.can('master:product:update'):auth.can('process:package:edit')&&record.status==='ACTIVE'" type="link" @click="open(record.id,true)">编辑</a-button></template><template v-else-if="column.key==='packageName'">{{record.packageName||'未命名（历史工艺）'}}</template><template v-else-if="column.key==='definitionStatus'">{{record.currentDefinition?.status==='EFFECTIVE'?'配置可用':'待完善'}}</template><template v-else-if="column.key==='operations'">{{record.currentDefinition?.route?.operations?.length??0}}</template><template v-else-if="column.key==='scope'">{{productScope(record)}}</template><a-tag v-else-if="column.key==='status'">{{states[record.status]??'—'}}</a-tag></template></a-table><div class="table-footer"><span role="status" aria-live="polite" aria-atomic="true">共 {{data.total}} 条</span><a-pagination :current="data.page+1" :page-size="data.size" :total="data.total" :show-size-changer="false" @change="(p:number)=>load(p-1)"/></div></a-card></main></template>

<style scoped>
#app .process-package-list .query-form{display:flex;flex-wrap:wrap;gap:12px 16px;align-items:center;justify-content:flex-start}
#app .process-package-list .query-form>label{flex:none;gap:8px;align-items:center}
#app .process-package-list .query-form>.ant-space{margin-left:0;justify-self:start}
.process-package-list :deep(.process-code-cell),.process-package-list :deep(.process-name-cell),.process-package-list :deep(.process-scope-cell){white-space:normal;overflow-wrap:anywhere;word-break:break-word}
</style>
